return [
    "CREATE TABLE catalog_tax_rules (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name VARCHAR(120) NOT NULL,rate DECIMAL(16,12) NOT NULL CHECK(rate>=0 AND rate<=1),inclusive BOOLEAN NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6))".$suffix,
    "CREATE TABLE catalog_categories (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name VARCHAR(120) NOT NULL,tax_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(tax_id) REFERENCES catalog_tax_rules(id))".$suffix,
    "CREATE TABLE catalog_cycles (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name VARCHAR(120) NOT NULL,kind VARCHAR(16) CHARACTER SET ascii NOT NULL CHECK(kind IN ('ONCE','DAYS','MONTHS')),interval_count SMALLINT UNSIGNED NOT NULL,CHECK ((kind='ONCE' AND interval_count=0) OR (kind<>'ONCE' AND interval_count BETWEEN 1 AND 3660)),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6))".$suffix,
    "CREATE TABLE catalog_items (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,kind VARCHAR(16) CHARACTER SET ascii NOT NULL CHECK(kind IN ('PRODUCT','VARIANT','OPTION','ADDON')),name VARCHAR(120) NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6))".$suffix,
    "CREATE TABLE catalog_products (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,product_type VARCHAR(16) CHARACTER SET ascii NOT NULL CHECK(product_type IN ('HOSTING','DOMAIN','CLOUD')),sale_status VARCHAR(16) CHARACTER SET ascii NOT NULL DEFAULT 'DRAFT' CHECK(sale_status IN ('DRAFT','ACTIVE','CLOSED')),tax_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,pricing_strategy VARCHAR(24) CHARACTER SET ascii NOT NULL CHECK(pricing_strategy IN ('SOURCE_FX','FIXED_PER_CURRENCY','FIXED_THEN_FX')),source_currency CHAR(3) CHARACTER SET ascii NOT NULL,activation_policy VARCHAR(16) CHARACTER SET ascii NOT NULL CHECK(activation_policy IN ('AUTO','MANUAL')),refund_policy VARCHAR(16) CHARACTER SET ascii NOT NULL CHECK(refund_policy IN ('none','prorated','staff_approval')),FOREIGN KEY(id) REFERENCES catalog_items(id),FOREIGN KEY(category_id) REFERENCES catalog_categories(id),FOREIGN KEY(tax_id) REFERENCES catalog_tax_rules(id))".$suffix,
    "CREATE TABLE catalog_variants (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,FOREIGN KEY(id) REFERENCES catalog_items(id),FOREIGN KEY(product_id) REFERENCES catalog_products(id))".$suffix,
    "CREATE TABLE catalog_option_groups (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(120) NOT NULL,required BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(product_id) REFERENCES catalog_products(id))".$suffix,
    "CREATE TABLE catalog_option_values (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,group_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,FOREIGN KEY(id) REFERENCES catalog_items(id),FOREIGN KEY(group_id) REFERENCES catalog_option_groups(id))".$suffix,
