    "CREATE TABLE catalog_prices (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,cycle_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,amount DECIMAL(24,10) NOT NULL CHECK(amount>=0),version BIGINT UNSIGNED NOT NULL,published_by VARCHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_price_version(item_id,cycle_id,currency,version),FOREIGN KEY(item_id) REFERENCES catalog_items(id),FOREIGN KEY(cycle_id) REFERENCES catalog_cycles(id))".$suffix,
