    "CREATE TABLE catalog_provider_mappings (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,provider VARCHAR(24) CHARACTER SET ascii NOT NULL CHECK(provider IN ('cpanel','voyar','resellerclub','domainnameapi')),plan_reference VARCHAR(128) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(item_id) REFERENCES catalog_items(id))".$suffix,
    "CREATE TABLE catalog_promotions (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,rate DECIMAL(16,12) NOT NULL CHECK(rate>0 AND rate<=1),period_scope VARCHAR(16) CHARACTER SET ascii NOT NULL CHECK(period_scope IN ('FIRST','RECURRING','ALL')),combinable BOOLEAN NOT NULL,max_uses INT UNSIGNED NOT NULL CHECK(max_uses>0),per_customer_limit INT UNSIGNED NOT NULL CHECK(per_customer_limit>0),starts_at DATETIME(6) NOT NULL,ends_at DATETIME(6) NOT NULL,product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),CHECK(ends_at>starts_at),FOREIGN KEY(product_id) REFERENCES catalog_products(id),FOREIGN KEY(category_id) REFERENCES catalog_categories(id))".$suffix,
